import { chromium } from "playwright-core";
import http from "node:http";
import fs from "node:fs";
import path from "node:path";

const root = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const chrome = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";

function makeStep(streamIdx, pi, p0) {
  return {
    stream_idx: streamIdx,
    pi,
    Gi: [
      [pi[0] - 0.4, pi[1] - 0.4],
      [pi[0] + 0.4, pi[1] - 0.4],
      [pi[0] + 0.4, pi[1] + 0.4],
      [pi[0] - 0.4, pi[1] + 0.4],
    ],
    buffer: [p0, pi],
    candidates: [{ grid_pt_idx: 0, alive: true, F: [], S: [] }],
  };
}

const p0 = [0, 0];
const p1 = [2, 1];
const p2 = [4, 0];
const ndjson = [
  {
    type: "header",
    eps: 0.9,
    delta: 500,
    grid_val: 12.5,
    r_val: 8.2,
    expected_frechet: 1.25,
    bbox: [-1, -1, 6, 3],
    stream: [p0, p1, p2],
  },
  {
    type: "prefix",
    data: {
      start_idx: 0,
      end_idx: 2,
      p0_idx: 0,
      p0,
      P: [[0.2, 0.2], [0.3, -0.1]],
      output: [p0, p2],
      steps: [makeStep(1, p1, p0), makeStep(2, p2, p0)],
    },
  },
  { type: "done", time_ms: 12.4, simplified: [p0, p2], frechet_distance: 0.41 },
].map((o) => JSON.stringify(o)).join("\n") + "\n";

function mime(filePath) {
  if (filePath.endsWith(".js")) return "text/javascript";
  if (filePath.endsWith(".css")) return "text/css";
  if (filePath.endsWith(".html")) return "text/html";
  if (filePath.endsWith(".svg")) return "image/svg+xml";
  return "application/octet-stream";
}

let releaseTrace;
const traceGate = new Promise((resolve) => { releaseTrace = resolve; });

const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://127.0.0.1");
  if (url.pathname === "/api/traces") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ traces: [{ id: 1, n_points: 3, label: "Demo" }] }));
    return;
  }
  if (url.pathname.startsWith("/api/trace")) {
    traceGate.then(() => {
      res.writeHead(200, { "Content-Type": "application/x-ndjson" });
      res.end(ndjson);
    });
    return;
  }
  if (url.pathname === "/api/frechet") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ distance: 0.4123 }));
    return;
  }
  const filePath = url.pathname === "/"
    ? path.join(root, "index.html")
    : path.join(root, url.pathname.replace(/^\//, ""));
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404);
      res.end("not found");
      return;
    }
    res.writeHead(200, { "Content-Type": mime(filePath) });
    res.end(data);
  });
});

await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const origin = `http://127.0.0.1:${server.address().port}`;
const browser = await chromium.launch({ executablePath: chrome, headless: true });

function measure(page) {
  return page.evaluate(() => {
    const box = (sel) => {
      const n = typeof sel === "string" ? document.querySelector(sel) : sel;
      if (!n) return null;
      const r = n.getBoundingClientRect();
      const cs = getComputedStyle(n);
      return {
        id: n.id || n.className?.toString?.().slice(0, 40),
        x: Math.round(r.x),
        y: Math.round(r.y),
        w: Math.round(r.width),
        h: Math.round(r.height),
        right: Math.round(r.right),
        bottom: Math.round(r.bottom),
        display: cs.display,
        wrap: cs.flexWrap,
        whiteSpace: cs.whiteSpace,
        text: (n.innerText || "").replace(/\s+/g, " ").slice(0, 80),
      };
    };
    const header = document.querySelector("header");
    const kids = [...header.children].map((n) => box(n));
    const formKids = [...document.querySelector(".upload-form").children].map((n) => box(n));
    return {
      vw: window.innerWidth,
      header: box("header"),
      h1: box("header h1"),
      fileControls: box(".file-controls"),
      uploadForm: box(".upload-form"),
      uploadStatus: box("#uploadStatus"),
      loadBtn: box("#loadBtn"),
      params: box("#paramsBar"),
      headerKids: kids,
      formKids,
    };
  });
}

try {
  const page = await browser.newPage({ viewport: { width: 900, height: 700 }, deviceScaleFactor: 1 });
  await page.goto(origin, { waitUntil: "domcontentloaded" });
  await page.waitForFunction(() => {
    const sel = document.getElementById("traceSelect");
    return sel && [...sel.options].some((o) => o.value === "1");
  }, { timeout: 8000 });
  await page.selectOption("#traceSelect", "1");
  await page.click("#loadBtn");
  await page.waitForFunction(() => document.body.classList.contains("trace-loading"), { timeout: 8000 });
  await page.waitForTimeout(300);
  const loading = await measure(page);
  await page.screenshot({ path: "/tmp/pwshot/header-900-loading-before.png" });

  releaseTrace();
  await page.waitForFunction(() => document.body.classList.contains("playback-ready"), { timeout: 8000 });
  await page.waitForTimeout(400);
  try { await page.evaluate(() => window.MathJax?.typesetPromise?.()); } catch {}
  await page.waitForTimeout(300);
  const loaded = await measure(page);
  await page.screenshot({ path: "/tmp/pwshot/header-900-loaded-before.png" });

  const result = { loading, loaded };
  fs.writeFileSync("/tmp/pwshot/header-900-measure.json", JSON.stringify(result, null, 2));
  console.log(JSON.stringify(result, null, 2));
  await page.close();
} finally {
  await browser.close();
  server.close();
}

